	/**
	 * Default Constructor
	 */
    public KycProfileService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new KycProfileEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(KycProfileRepository.class) );
		this.validator		= applicationContext.getBean(KycProfileValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		KycProfile
	 */
		public KycProfile createKycProfile( CreateKycProfileCommand command ) {

		KycProfile entity = new KycProfile();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setKycProfileId( command.getKycProfileId() );
            entity.setProfileId( command.getProfileId() );
            entity.setLastReviewedOn( command.getLastReviewedOn() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of KycProfile {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateKycProfileCommand
	 * @return		KycProfile
	 */
	public KycProfile updateKycProfile( UpdateKycProfileCommand command ) {

		KycProfile entity = new KycProfile();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setKycProfileId( command.getKycProfileId() );
            entity.setProfileId( command.getProfileId() );
            entity.setLastReviewedOn( command.getLastReviewedOn() );
            entity.setCustomer( command.getCustomer() );
            entity.setIdentityDocuments( command.getIdentityDocuments() );
            entity.setRiskAssessments( command.getRiskAssessments() );
            entity.setScreenings( command.getScreenings() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of KycProfile {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteKycProfileCommand
	 */
	public void delete( DeleteKycProfileCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getKycProfileId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of KycProfile {0} ", id );

	}

	/**
	 * Method to retrieve the KycProfile via KycProfileFetchOneSummary
	 * @param 	summary KycProfileFetchOneSummary
	 * @return 	KycProfileFetchOneResponse
	 */
	public KycProfile getKycProfile( KycProfileFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "KycProfileFetchOneSummary arg cannot be null" );

		KycProfile entity = null;
		UUID id = summary.getKycProfileId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a KycProfile using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all KycProfiles
	 *
	 * @return 	List<KycProfile>
	 */
    public List<KycProfile> getAllKycProfile() {
		List<KycProfile> list = projector.findAll( new FindAllKycProfileQuery() );
		return list;
	}

	/**
	 * assign Customer on KycProfile
	 * @param		command AssignCustomerToKycProfileCommand
	 */
	public void assignCustomer( AssignCustomerToKycProfileCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getKycProfileId(), command.getAssignment());

	}

